/**
 * The catalogue of every error the API can return.
 *
 * Each error has a stable machine-readable `code`. The web and mobile apps decide what to do from
 * the CODE (for example show a field message, or ask for manager approval), never from the English
 * text, which can change. Once a code is published do not rename it.
 *
 * To add an error: add a line here. That is the only place; the filter, the Swagger helper and
 * `docs/api/error-codes.md` (generated by `pnpm docs:errors`) all read this list.
 */
export interface ErrorCodeInfo {
  /** HTTP status sent with this error. */
  status: number;
  /** Short title (not translated; the apps show their own wording based on the code). */
  title: string;
  /** What the app should do when it receives this code. Appears in the generated documentation. */
  uiHint: string;
}

